/**
* Composable for handling subgraph-related operations
*/
function useSubgraphOperations() {
	const { getSelectedNodes } = useSelectedLiteGraphItems();
	const canvasStore = useCanvasStore();
	const workflowStore = useWorkflowStore();
	const nodeOutputStore = useNodeOutputStore();
	const subgraphStore = useSubgraphStore();
	const toastStore = useToastStore();
	const convertToSubgraph = () => {
		const canvas = canvasStore.getCanvas();
		const graph = canvas.subgraph ?? canvas.graph;
		if (!graph) return null;
		const { node } = graph.convertToSubgraph(canvas.selectedItems);
		canvas.select(node);
		workflowStore.activeWorkflow?.changeTracker.captureCanvasState();
	};
	const doUnpack = (subgraphNodes, skipMissingNodes) => {
		const canvas = canvasStore.getCanvas();
		const graph = canvas.subgraph ?? canvas.graph;
		if (!graph) return;
		let changed = false;
		let refused = false;
		for (const subgraphNode of subgraphNodes) {
			if (!graph.unpackSubgraph(subgraphNode, { skipMissingNodes })) {
				refused = true;
				continue;
			}
			nodeOutputStore.revokeSubgraphPreviews(subgraphNode, graph);
			changed = true;
		}
		if (refused) toastStore.add({
			severity: "error",
			summary: t("g.error"),
			detail: t("g.subgraphUnpackFailed")
		});
		if (changed) workflowStore.activeWorkflow?.changeTracker.captureCanvasState();
	};
	const unpackSubgraph = () => {
		const canvas = canvasStore.getCanvas();
		if (!(canvas.subgraph ?? canvas.graph)) return;
		const subgraphNodes = Array.from(canvas.selectedItems).filter((item) => item instanceof SubgraphNode);
		if (subgraphNodes.length === 0) return;
		doUnpack(subgraphNodes, true);
	};
	const addSubgraphToLibrary = async () => {
		if (Array.from(canvasStore.selectedItems).filter((item) => item instanceof SubgraphNode).length !== 1) return;
		await subgraphStore.publishSubgraph();
	};
	const isSubgraphSelected = () => {
		return Array.from(canvasStore.selectedItems).some((item) => item instanceof SubgraphNode);
	};
	const hasSelectableNodes = () => {
		return getSelectedNodes().length > 0;
	};
	return {
		convertToSubgraph,
		unpackSubgraph,
		addSubgraphToLibrary,
		isSubgraphSelected,
		hasSelectableNodes
	};
}
