//#region src/composables/node/useNodeAnimatedImage.ts
/**
* Composable for handling animated image previews in nodes
*/
function useNodeAnimatedImage() {
	/**
	* Shows animated image preview for a node
	* @param node The graph node to show the preview for
	*/
	function showAnimatedPreview(node) {
		if (!node.imgs?.length) return;
		if (!node.widgets) return;
		const widgetIdx = node.widgets.findIndex((w) => w.name === ANIM_PREVIEW_WIDGET);
		node.imgs[0].classList.value = "block size-full object-contain";
		if (widgetIdx > -1) {
			const widget = node.widgets[widgetIdx];
			if (!isDOMWidget(widget)) return;
			widget.element.replaceChildren(node.imgs[0]);
		} else {
			const element = document.createElement("div");
			element.appendChild(node.imgs[0]);
			const widget = node.addDOMWidget(ANIM_PREVIEW_WIDGET, "img", element, {
				hideOnZoom: false,
				surfaces: {
					canvas: "shown",
					vueNode: "never",
					panel: "never"
				}
			});
			node.overIndex = 0;
			const { handleWheel, handlePointerDown, handlePointerMove, handlePointerUp, forwardEventToCanvas } = useCanvasInteractions();
			node.imgs[0].style.pointerEvents = "none";
			const controller = new AbortController();
			const { signal } = controller;
			element.addEventListener("wheel", handleWheel, { signal });
			element.addEventListener("pointermove", handlePointerMove, { signal });
			element.addEventListener("pointerup", handlePointerUp, { signal });
			element.addEventListener("pointerdown", (e) => e.button !== 2 ? handlePointerDown(e) : forwardEventToCanvas(e), {
				capture: true,
				signal
			});
			widget.onRemove = useChainCallback(widget.onRemove, () => {
				controller.abort();
			});
			widget.serialize = false;
			widget.serializeValue = () => void 0;
		}
	}
	/**
	* Removes animated image preview from a node
	* @param node The graph node to remove the preview from
	*/
	function removeAnimatedPreview(node) {
		if (!node.widgets) return;
		const widgetIdx = node.widgets.findIndex((w) => w.name === ANIM_PREVIEW_WIDGET);
		if (widgetIdx > -1) {
			node.widgets[widgetIdx].onRemove?.();
			node.widgets.splice(widgetIdx, 1);
		}
	}
	return {
		showAnimatedPreview,
		removeAnimatedPreview
	};
}
