//#region src/platform/assets/utils/resolveModelNodeFromAsset.ts
/**
* Resolves an asset item to the node provider and filename needed to add a
* model loader node. Validation failures return error results rather than
* throwing, so callers can degrade gracefully in UI contexts.
*/
function resolveModelNodeFromAsset(asset) {
	const validatedAsset = assetItemSchema.safeParse(asset);
	if (!validatedAsset.success) {
		const errorMessage = validatedAsset.error.errors.map((e) => `${e.path.join(".")}: ${e.message}`).join(", ");
		console.error("Invalid asset item:", errorMessage);
		return {
			success: false,
			error: {
				code: "INVALID_ASSET",
				message: "Asset schema validation failed",
				assetId: typeof asset.id === "string" ? asset.id : "unknown",
				details: { validationErrors: errorMessage }
			}
		};
	}
	const validAsset = validatedAsset.data;
	const filename = getAssetFilename(validAsset);
	if (filename.length === 0) {
		console.error(`Asset ${validAsset.id} has invalid user_metadata.filename (expected non-empty string, got ${typeof filename})`);
		return {
			success: false,
			error: {
				code: "INVALID_ASSET",
				message: `Invalid filename (expected non-empty string, got ${typeof filename})`,
				assetId: validAsset.id
			}
		};
	}
	if (validAsset.tags.length === 0) {
		console.error(`Asset ${validAsset.id} has no tags defined (expected at least one category tag)`);
		return {
			success: false,
			error: {
				code: "INVALID_ASSET",
				message: "Asset has no tags defined",
				assetId: validAsset.id
			}
		};
	}
	const { flags } = useFeatureFlags();
	const candidates = getAssetNodeCategoryCandidates(validAsset, flags.supportsModelTypeTags);
	if (candidates.length === 0) {
		console.error(`Asset ${validAsset.id} has no valid category tag. Available tags: ${validAsset.tags.join(", ")} (expected tag other than '${MODELS_TAG}' or '${MISSING_TAG}')`);
		return {
			success: false,
			error: {
				code: "INVALID_ASSET",
				message: "Asset has no valid category tag",
				assetId: validAsset.id,
				details: { availableTags: validAsset.tags }
			}
		};
	}
	const modelToNodeStore = useModelToNodeStore();
	const resolved = candidates.map((category) => ({
		category,
		provider: modelToNodeStore.getNodeProvider(category)
	})).find((candidate) => candidate.provider !== void 0);
	if (!resolved?.provider) {
		console.error(`No node provider registered for category: ${candidates.join(", ")}`);
		return {
			success: false,
			error: {
				code: "NO_PROVIDER",
				message: `No node provider registered for category: ${candidates.join(", ")}`,
				assetId: validAsset.id,
				details: { candidates }
			}
		};
	}
	return {
		success: true,
		value: {
			provider: resolved.provider,
			filename
		}
	};
}
//#endregion
//#region src/composables/node/startModelNodeDragFromAsset.ts
/**
* Arms a ghost drag for a model loader node. Providers with no widget key
* (auto-load nodes) start the drag without widget values.
*/
function startModelLoaderDrag(provider, filename, source = "sidebar_drag") {
	const widgetValues = provider.key ? { [provider.key]: filename } : void 0;
	useNodeDragToCanvas().startDrag(provider.nodeDef, {
		widgetValues,
		source
	});
}
/**
* Starts a ghost drag for the model loader node described by an asset. The
* node is created where the user next clicks the canvas, with the asset's
* filename written into the loader widget.
*
* @returns the resolution error when the asset cannot be mapped to a node,
*   otherwise `undefined`.
*/
function startModelNodeDragFromAsset(asset, source = "sidebar_drag") {
	const resolved = resolveModelNodeFromAsset(asset);
	if (!resolved.success) return resolved.error;
	const { provider, filename } = resolved.value;
	startModelLoaderDrag(provider, filename, source);
}
