//#region src/platform/assets/composables/openModelLibraryBrowser.ts
async function openModelLibraryBrowser() {
	if (!useFeatureFlags().flags.assetsEnabled) return;
	const toastStore = useToastStore();
	await useAssetBrowserDialog().browse({
		assetType: "models",
		title: t("sideToolbar.modelLibrary"),
		onAssetSelected: (asset) => {
			const error = startModelNodeDragFromAsset(asset, "asset_browser");
			if (error) {
				reportError(new Error(error.message), {
					surface: "assets",
					errorType: "model_node_creation_failure",
					tags: { code: error.code },
					context: {
						assetId: error.assetId,
						details: error.details
					}
				});
				toastStore.add({
					severity: "error",
					summary: t("g.error"),
					detail: t("assetBrowser.failedToCreateNode")
				});
			}
		}
	});
}
