//#region src/platform/telemetry/utils/getExecutionContext.ts
function getExecutionContext() {
	const workflowStore = useWorkflowStore();
	const templatesStore = useWorkflowTemplatesStore();
	const nodeDefStore = useNodeDefStore();
	const activeWorkflow = workflowStore.activeWorkflow;
	const nodeCounts = reduceAllNodes(app.rootGraph, (metrics, node) => {
		const nodeDef = nodeDefStore.fromLGraphNode(node);
		const isCustomNode = nodeDef?.nodeSource.type === NodeSourceType.CustomNodes;
		const isApiNode = nodeDef?.api_node;
		const isSubgraph = typeof node.isSubgraphNode === "function" && node.isSubgraphNode();
		if (isApiNode) {
			metrics.has_api_nodes = true;
			const canonicalName = nodeDef.name;
			if (canonicalName && !metrics.api_node_names.includes(canonicalName)) metrics.api_node_names.push(canonicalName);
		}
		const isToolkitNode = TOOLKIT_NODES.has(node.type);
		if (isToolkitNode) {
			metrics.has_toolkit_nodes = true;
			const trackingName = nodeDef?.name ?? node.type;
			if (!metrics.toolkit_node_names.includes(trackingName)) metrics.toolkit_node_names.push(trackingName);
		}
		metrics.custom_node_count += isCustomNode ? 1 : 0;
		metrics.api_node_count += isApiNode ? 1 : 0;
		metrics.toolkit_node_count += isToolkitNode ? 1 : 0;
		metrics.subgraph_count += isSubgraph ? 1 : 0;
		metrics.total_node_count += 1;
		return metrics;
	}, {
		custom_node_count: 0,
		api_node_count: 0,
		toolkit_node_count: 0,
		subgraph_count: 0,
		total_node_count: 0,
		has_api_nodes: false,
		api_node_names: [],
		has_toolkit_nodes: false,
		toolkit_node_names: []
	});
	if (activeWorkflow?.filename) {
		const templateName = activeWorkflow.fullFilename.replace(/\.json$/i, "");
		if (templatesStore.knownTemplateNames.has(templateName)) {
			const template = templatesStore.getTemplateByName(templateName);
			const englishMetadata = templatesStore.getEnglishMetadata(templateName);
			return {
				is_template: true,
				workflow_name: templateName,
				template_source: template?.sourceModule,
				template_category: englishMetadata?.category ?? template?.category,
				template_tags: englishMetadata?.tags ?? template?.tags,
				template_models: englishMetadata?.models ?? template?.models,
				template_use_case: englishMetadata?.useCase ?? template?.useCase,
				template_license: englishMetadata?.license ?? template?.license,
				...nodeCounts
			};
		}
		return {
			is_template: false,
			workflow_name: activeWorkflow.filename,
			...nodeCounts
		};
	}
	return {
		is_template: false,
		workflow_name: void 0,
		...nodeCounts
	};
}
