//#region src/platform/workflow/validation/composables/useWorkflowValidation.ts
function useWorkflowValidation() {
	const toastStore = useToastStore();
	function tryFixLinks(graphData, options = {}) {
		const { silent = false } = options;
		const logs = [];
		const linkValidation = fixBadLinks(graphData, {
			fix: true,
			silent,
			logger: { log: (...args) => {
				logs.push(args.join(" "));
			} }
		});
		if (!silent && logs.length > 0) toastStore.add({
			severity: "warn",
			summary: "Workflow Validation",
			detail: logs.join("\n")
		});
		if (linkValidation.fixed) {
			if (!silent) toastStore.add({
				severity: "success",
				summary: "Workflow Links Fixed",
				detail: `Fixed ${linkValidation.patched} node connections and removed ${linkValidation.deleted} invalid links.`
			});
		}
		return linkValidation.graph;
	}
	/**
	* Validates a workflow, including link validation and schema validation
	*/
	async function validateWorkflow(graphData, options = {}) {
		const { silent = false } = options;
		let validatedData = null;
		const validatedGraphData = await validateComfyWorkflow(graphData, (err) => {
			if (!silent) toastStore.addAlert(err);
		});
		if (validatedGraphData) try {
			validatedData = tryFixLinks(validatedGraphData, { silent });
		} catch (err) {
			console.error(err);
		}
		return { graphData: validatedData };
	}
	return { validateWorkflow };
}
