//#region src/platform/cloud/subscription/composables/useAccountPreconditionDialog.ts
function useAccountPreconditionDialog() {
	const dialogService = useDialogService();
	function open(precondition, context = {}) {
		switch (precondition) {
			case "sign_in":
				dialogService.showApiNodesSignInDialog(context.nodeType ? [context.nodeType] : []);
				return;
			case "subscription":
				dialogService.showSubscriptionRequiredDialog({ reason: context.source ?? "subscription_required" });
				return;
			case "credits": {
				const { fetchStatus, fetchBalance } = useBillingContext();
				Promise.allSettled([fetchStatus(), fetchBalance()]);
				dialogService.showTopUpCreditsDialog({
					isInsufficientCredits: true,
					...context.source && { source: context.source }
				});
				return;
			}
		}
	}
	return { open };
}
