//#region src/services/subgraphService.ts
var useSubgraphService = () => {
	const nodeDefStore = useNodeDefStore();
	/** Loads a single subgraph definition and registers it with the node def store */
	function registerLitegraphNode(nodeDef, subgraph, exportedSubgraph) {
		const instanceData = {
			id: -1,
			type: exportedSubgraph.id,
			pos: [0, 0],
			size: [100, 100],
			inputs: [],
			outputs: [],
			flags: {},
			order: 0,
			mode: 0
		};
		useLitegraphService().registerSubgraphNodeDef(nodeDef, subgraph, instanceData);
	}
	function createNodeDef(exportedSubgraph) {
		const { id, name } = exportedSubgraph;
		const nodeDef = {
			input: { required: {} },
			output: [],
			output_is_list: [],
			output_name: [],
			output_tooltips: [],
			name: id,
			display_name: name,
			description: exportedSubgraph.description || `Subgraph node for ${name}`,
			category: "subgraph",
			output_node: false,
			python_module: "nodes"
		};
		nodeDefStore.addNodeDef(nodeDef);
		return nodeDef;
	}
	/** Loads all exported subgraph definitions from workflow */
	function loadSubgraphs(graphData) {
		const subgraphs = graphData.definitions?.subgraphs;
		if (!subgraphs) return;
		const normalized = normalizeSubgraphDefinitionIds(subgraphs, graphData.nodes);
		graphData.definitions.subgraphs = normalized.subgraphs;
		if (normalized.rootNodes) graphData.nodes = normalized.rootNodes;
		const exportedSubgraphs = normalized.subgraphs;
		const missingSubgraphs = exportedSubgraphs.filter(({ id }) => !app.rootGraph.subgraphs.has(id));
		const createdSubgraphs = app.rootGraph.createSubgraphs(missingSubgraphs);
		const loadedSubgraphs = new Map(app.rootGraph.subgraphs);
		for (const [index, data] of missingSubgraphs.entries()) loadedSubgraphs.set(data.id, createdSubgraphs[index]);
		for (const subgraphData of exportedSubgraphs) {
			const subgraph = loadedSubgraphs.get(subgraphData.id);
			if (!subgraph) continue;
			registerNewSubgraph(subgraph, subgraphData);
		}
	}
	/** Registers a new subgraph (e.g. user converted from nodes) */
	function registerNewSubgraph(subgraph, exportedSubgraph) {
		registerLitegraphNode(createNodeDef(exportedSubgraph), subgraph, exportedSubgraph);
	}
	return {
		loadSubgraphs,
		registerNewSubgraph
	};
};
